wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(191358019763766827)
,p_name=>'P2_SOLICITANTE'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(186248258053183445)
,p_prompt=>'Solicitante'
,p_display_as=>'NATIVE_COMBOBOX'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT INITCAP(TRANSLATE(',
'           v.nom_pessoa,',
unistr('           ''\00C1\00C9\00CD\00D3\00DA\00C2\00CA\00CE\00D4\00DB\00C3\00D5\00C0\00C8\00CC\00D2\00D9\00C7\00E1\00E9\00ED\00F3\00FA\00E2\00EA\00EE\00F4\00FB\00E3\00F5\00E0\00E8\00EC\00F2\00F9\00E7'','),
'           ''AEIOUAEIOUAOAEIOUCaeiouaeiouaoaeiouc''',
'       )) AS d,',
'       v.num_cpf AS r',
'  FROM dda.vinculo_sf v',
' WHERE v.ind_vinculo_ativo = ''S''',
'    AND (',
'         :P2_EXIBIR = ''setor''',
'         AND v.sgl_orgao_exercicio IN (',
'             SELECT o.sgl_orgao',
'             FROM dda.orgao o',
'             WHERE o.sgl_orgao_hierarquia LIKE ''%'' || (',
'                 SELECT i.sgl_orgao_exercicio',
'                   FROM dda.vinculo_sf i',
'                  WHERE i.ind_vinculo_ativo = ''S''',
'                    AND i.num_cpf = ',
'                        CASE',
'                            WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                                THEN :APP_USER',
'                            ELSE (',
'                                SELECT u.num_cpf_pessoa',
'                                FROM dda.usuario_rede u',
'                                WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                            )',
'                        END',
'             ) || ''%''',
'         )',
'       )',
'    OR (',
'         :P2_EXIBIR = ''usuario''',
'         AND v.num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'       )',
' ORDER BY 1',
''))
,p_lov_cascade_parent_items=>'P2_EXIBIR'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_field_template=>wwv_flow_imp.id(141036243397608264)
