wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(141238674947674102)
,p_plug_name=>'Datas'
,p_region_name=>'DATAS_NORMAL'
,p_parent_plug_id=>wwv_flow_imp.id(141221788595616933)
,p_region_css_classes=>'calendario'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_escape_on_http_output=>'Y'
,p_plug_template=>wwv_flow_imp.id(140965489666608226)
,p_plug_display_sequence=>130
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ID_RESERVA,',
'       DAT_INICIO,',
'       DAT_FIM,',
'       TIP_RESERVAS,',
'       STATUS,',
'       NUM_PARTICIPANTES,',
'       TITULO_RESERVA,',
'       DES_RESERVA,',
'       COD_PESSOA,',
'       PENDENTE,',
'       LOC,',
'       CASE',
'           WHEN TIP_RESERVAS LIKE ''Porta-C%'' THEN LOC',
'           WHEN TIP_RESERVAS LIKE ''Porta-B%'' THEN LOC',
'           WHEN TIP_RESERVAS IN (''Adesivagem'', ''Mezanino'') THEN TITULO_RESERVA',
'           ELSE DES_RESERVA',
'       END AS descricao_real,',
'       CASE',
'           WHEN STATUS = ''Em Andamento'' THEN ''pendentes''',
'           WHEN PENDENTE = ''N'' AND LPAD(COD_PESSOA, 11, ''0'') = ',
'                CASE',
'                    WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                        THEN :APP_USER',
'                    ELSE (',
'                        SELECT u.num_cpf_pessoa',
'                        FROM dda.usuario_rede u',
'                        WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                    )',
'                END',
'            THEN ''reservas-usuario''',
'           WHEN PENDENTE = ''N'' AND LPAD(COD_PESSOA, 11, ''0'') <>',
'                CASE',
'                    WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                        THEN :APP_USER',
'                    ELSE (',
'                        SELECT u.num_cpf_pessoa',
'                        FROM dda.usuario_rede u',
'                        WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                    )',
'                END',
'            THEN ''reservas-outro''',
'       END AS colorir_pendente',
'  FROM RESERVAS',
' WHERE ( :P3_TIP_RESERVAS IS NULL OR UPPER(TIP_RESERVAS) = UPPER(:P3_TIP_RESERVAS) )',
'   AND STATUS NOT IN (''Cancelado'')',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CSS_CALENDAR'
,p_ajax_items_to_submit=>'P3_TIP_RESERVAS'
,p_attribute_01=>'DAT_INICIO'
,p_attribute_02=>'DAT_FIM'
,p_attribute_03=>'DESCRICAO_REAL'
,p_attribute_04=>'ID_RESERVA'
,p_attribute_05=>'f?p=&APP_ID.:105:&SESSION.::&DEBUG.:105:P105_ID_RESERVA:&ID_RESERVA.'
,p_attribute_06=>'f?p=&APP_ID.:104:&SESSION.::&DEBUG.:104:P104_DAT_FIM,P104_DAT_INICIO:&APEX$NEW_END_DATE.,&APEX$NEW_START_DATE.'
,p_attribute_07=>'N'
,p_attribute_09=>'list:navigation'
,p_attribute_13=>'N'
,p_attribute_14=>'COLORIR_PENDENTE'
,p_attribute_17=>'Y'
,p_attribute_19=>'Y'
,p_attribute_21=>'10'
,p_attribute_22=>'Y'
