,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(140955698394608223)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ID_RESERVA,',
'       DAT_INICIO,',
'       DAT_FIM,',
'       TIP_RESERVAS,',
'       CASE ',
'         WHEN num_participantes IS NULL THEN ''---'' ',
'         ELSE TO_CHAR(num_participantes) ',
'       END AS num_participantes,',
'       TITULO_RESERVA,',
'       DES_RESERVA,',
'       COD_PESSOA,',
'       PENDENTE,',
'       CASE ',
'         WHEN loc IS NULL THEN ''N/A'' ',
'         ELSE loc ',
'       END AS local,',
'       CASE ',
'         WHEN obs IS NULL THEN ''N/A'' ',
'         ELSE obs ',
'       END AS observacao,',
'       dbms_lob.getlength(ARQ) as foto',
'  from RESERVAS',
'  where PENDENTE = ''S''',
'    and tip_reservas <> ''Mezanino''',
'    and LPAD(COD_PESSOA, 11, ''0'') = ',
'        CASE',
'            WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                THEN :APP_USER',
'            ELSE (',
'                SELECT u.num_cpf_pessoa',
'                FROM dda.usuario_rede u',
'                WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'            )',
'        END',
'  order by dat_inicio, tip_RESERVAS, id_reserva'))
