wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(141241088716674126)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adicionar aos Pendentes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob          BLOB;',
'    l_mime          VARCHAR2(200);',
'    l_filename      VARCHAR2(200);',
'    l_data_ini      DATE;',
'    l_data_fim      DATE;',
'    l_id_reserva    reservas.id_reserva%TYPE;',
'    l_locais        APEX_T_VARCHAR2; -- array para armazenar os locais',
'BEGIN',
unistr('    -- Determina a data de in\00EDcio e fim'),
'    IF :P3_TIP_RESERVAS = ''Mezanino'' THEN',
'        SELECT MIN(dat), MAX(dat)',
'          INTO l_data_ini, l_data_fim',
'          FROM TMP_RESERVAS',
'         WHERE LPAD(cpf_solicitante, 11, ''0'') = :P3_COD_PESSOA;',
'    ELSE',
'        l_data_ini := TO_TIMESTAMP(:P3_DAT_INICIO, ''DD/MM/YYYY HH24:MI:SS'');',
'        l_data_fim := TO_TIMESTAMP(:P3_DAT_FIM, ''DD/MM/YYYY HH24:MI:SS'');',
'    END IF;',
'',
'    IF l_data_ini IS NULL OR l_data_fim IS NULL THEN',
unistr('        RAISE_APPLICATION_ERROR(-20011, ''As datas de in\00EDcio e fim devem ser informadas.'');'),
'    END IF;',
'',
'    IF :P3_TIP_RESERVAS LIKE ''Porta-%'' THEN',
'        IF :P3_LOC IS NULL OR TRIM(:P3_LOC) = '''' THEN',
'            RAISE_APPLICATION_ERROR(-20010, ''Por favor, selecione um local para a reserva.'');',
'        END IF;',
'    END IF;',
'',
'    -- Divide o campo de locais apenas se existir',
'    IF :P3_LOC IS NOT NULL THEN',
'        l_locais := APEX_STRING.SPLIT(:P3_LOC, '':'');',
'    ELSE',
'        l_locais := APEX_T_VARCHAR2();',
'    END IF;',
'',
'    -- Se houver arquivo anexado',
'    IF :P3_ARQ IS NOT NULL THEN',
'        SELECT blob_content, mime_type, filename',
'          INTO l_blob, l_mime, l_filename',
'          FROM apex_application_temp_files',
'         WHERE name = :P3_ARQ;',
'    END IF;',
'',
unistr('    -- Se for Mezanino ou Adesivagem \00BF insere uma \00FAnica reserva sem local'),
'    IF :P3_TIP_RESERVAS IN (''Mezanino'', ''Adesivagem'') THEN',
'        INSERT INTO reservas (',
'            id_reserva,',
'            dat_inicio,',
'            dat_fim,',
'            tip_reservas,',
'            status,',
'            loc,',
'            num_participantes,',
'            titulo_reserva,',
'            des_reserva,',
'            cod_pessoa,',
'            pendente,',
'            obs,',
'            arq,',
'            mimetype,',
'            filename,',
'            email_enviado,',
'            dat_criacao',
'        ) VALUES (',
'            SEQ_RESERVAS.NEXTVAL,',
'            l_data_ini,',
'            l_data_fim,',
'            :P3_TIP_RESERVAS,',
'            :P3_STATUS,',
'            NULL,  -- sem local',
'            :P3_NUM_PARTICIPANTES,',
'            :P3_TITULO_RESERVA,',
'            :P3_DES_RESERVA,',
'            :P3_COD_PESSOA,',
'            :P3_PENDENTE,',
'            :P3_OBS,',
'            CASE WHEN :P3_ARQ IS NOT NULL THEN l_blob ELSE NULL END,',
'            CASE WHEN :P3_ARQ IS NOT NULL THEN l_mime ELSE NULL END,',
'            CASE WHEN :P3_ARQ IS NOT NULL THEN l_filename ELSE NULL END,',
'            ''N'',',
'            SYSDATE',
'        )',
'        RETURNING id_reserva INTO l_id_reserva;',
'',
unistr('        -- Caso seja Mezanino \00BF insere os hor\00E1rios'),
'        IF :P3_TIP_RESERVAS = ''Mezanino'' THEN',
'            INSERT INTO horarios_mezanino (',
'                id_horario,',
'                id_reserva,',
'                dat,',
'                hor_inicio,',
'                hor_fim',
'            )',
'            SELECT',
'                SEQ_HORARIOS_MEZANINO.NEXTVAL,',
'                l_id_reserva,',
'                dat,',
'                hor_inicio,',
'                hor_fim',
'            FROM tmp_reservas',
'            WHERE LPAD(cpf_solicitante, 11, ''0'') = :P3_COD_PESSOA;',
'        END IF;',
'',
'    ELSE',
unistr('        -- Caso tenha locais \00BF insere uma reserva por local'),
'        FOR i IN 1 .. l_locais.COUNT LOOP',
'            INSERT INTO reservas (',
'                id_reserva,',
'                dat_inicio,',
'                dat_fim,',
'                tip_reservas,',
'                status,',
'                loc,',
'                num_participantes,',
'                titulo_reserva,',
'                des_reserva,',
'                cod_pessoa,',
'                pendente,',
'                obs,',
'                arq,',
'                mimetype,',
'                filename,',
'                email_enviado,',
'                dat_criacao',
'            ) VALUES (',
'                SEQ_RESERVAS.NEXTVAL,',
'                l_data_ini,',
'                l_data_fim,',
'                :P3_TIP_RESERVAS,',
'                :P3_STATUS,',
'                TRIM(l_locais(i)),',
'                :P3_NUM_PARTICIPANTES,',
'                :P3_TITULO_RESERVA,',
'                :P3_DES_RESERVA,',
'                :P3_COD_PESSOA,',
'                :P3_PENDENTE,',
'                :P3_OBS,',
'                CASE WHEN :P3_ARQ IS NOT NULL THEN l_blob ELSE NULL END,',
'                CASE WHEN :P3_ARQ IS NOT NULL THEN l_mime ELSE NULL END,',
'                CASE WHEN :P3_ARQ IS NOT NULL THEN l_filename ELSE NULL END,',
'                ''N'',',
'                SYSDATE',
'            )',
'            RETURNING id_reserva INTO l_id_reserva;',
'        END LOOP;',
'    END IF;',
'',
unistr('    -- Limpa a tabela tempor\00E1ria'),
'    DELETE FROM tmp_reservas',
'     WHERE LPAD(cpf_solicitante, 11, ''0'') = :P3_COD_PESSOA;',
'',
'    :P3_ID_RESERVA := l_id_reserva;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>141241088716674126
);
end;
/
