,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT r.ID_RESERVA,',
'       r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       r.STATUS,',
'       r.NUM_PARTICIPANTES,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       r.COD_PESSOA,',
'       r.LOC,',
'       r.OBS,',
'       dbms_lob.getlength(r.ARQ) AS foto',
'FROM RESERVAS r',
'WHERE r.pendente = ''S''',
'  AND r.tip_reservas <> ''Mezanino''',
'  AND LPAD(r.COD_PESSOA, 11, ''0'') = ',
'      CASE',
'          WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'              THEN :APP_USER',
'          ELSE (',
'              SELECT u.num_cpf_pessoa',
'              FROM dda.usuario_rede u',
'              WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'          )',
'      END',
'  AND EXISTS (',
'      SELECT 1',
'      FROM dda.vinculo_sf v',
'      WHERE v.num_cpf = LPAD(r.COD_PESSOA, 11, ''0'')',
'        AND v.ind_vinculo_Ativo = ''S''',
'  );',
''))
