wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(141427581228009905)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Alterar o Campo Pendente'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_nome          VARCHAR2(200);',
'    v_id_grupo      NUMBER;',
'    v_qtd_reservas  NUMBER;',
'    v_email_destino     VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
'    v_assunto       VARCHAR2(200);',
'    v_mensagem      CLOB;',
'    v_bloco_reserva CLOB;',
'    v_total_andamento   NUMBER;',
'BEGIN',
'    -- Seleciona a quantidade de reservas a serem confirmadas por aquele solicitante',
'    SELECT COUNT(*) INTO v_qtd_reservas',
'    FROM reservas',
'    WHERE pendente = ''S''',
'        AND LPAD(COD_PESSOA, 11, ''0'') = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'',
'    IF v_qtd_reservas = 0 THEN',
'        apex_error.add_error(',
unistr('            p_message => ''Voc\00EA n\00E3o possui nenhuma reserva pendente para confirmar.'','),
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'        RETURN;',
'    END IF;',
'',
'    SELECT nom_pessoa INTO v_nome',
'    FROM dda.vinculo_sf',
'    WHERE num_cpf = ',
'        CASE',
'            WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                THEN :APP_USER',
'            ELSE (',
'                SELECT u.num_cpf_pessoa',
'                FROM dda.usuario_rede u',
'                WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'            )',
'        END',
'        AND ind_vinculo_ativo = ''S'';',
'',
'    SELECT SEQ_GRUPO_RESERVA.NEXTVAL INTO v_id_grupo FROM DUAL;',
'',
'    -- Coloca um grupo de reservas para aquelas reservas',
'    UPDATE reservas',
'    SET COD_GRUPO_RESERVA = v_id_grupo',
'    WHERE pendente = ''S''',
'        AND LPAD(COD_PESSOA, 11, ''0'') = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'        AND cod_grupo_reserva IS NULL;',
'',
unistr('    -- Para cada reserva a ser confirmada pelo solicitante, a reserva \00E9 confirmada.'),
'    FOR r IN (',
'        SELECT id_reserva',
'        FROM reservas',
'        WHERE pendente = ''S''',
'            AND LPAD(COD_PESSOA, 11, ''0'') = ',
'                CASE',
'                    WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                        THEN :APP_USER',
'                    ELSE (',
'                        SELECT u.num_cpf_pessoa',
'                        FROM dda.usuario_rede u',
'                        WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                    )',
'                END',
'    )',
'    LOOP    -- Insere no atendimento de cada reserva que ela foi registrada',
'        INSERT INTO atendimento_reservas (',
'            dat_criacao_atendimento,',
'            des_atendimento,',
'            nom_atendimento,',
'            fk_atendimento_reservas_reservas,',
'            confirmado',
'        ) VALUES (',
'            SYSDATE,',
unistr('            ''Registro da Solicita\00E7\00E3o'','),
'            v_nome,',
'            r.id_reserva,',
'            ''S''',
'        );',
'    END LOOP;',
'',
'    UPDATE reservas',
'     SET pendente = ''N'' ',
'     WHERE pendente = ''S'' ',
'     AND LPAD(cod_pessoa, 11, ''0'') = ',
'        CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'',
'    BEGIN',
'        SELECT txt_email_sf INTO v_email_destino',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'        ',
unistr('        v_assunto := ''Confirma\00E7\00E3o de Solicita\00E7\00E3o de Reservas'';'),
'',
'        v_mensagem := ''<p>Prezado(a) <strong>'' || v_nome || ''</strong>,</p>'' ||',
unistr('                      ''<p>Informamos que suas solicita\00E7\00F5es de reserva foram registradas com sucesso no sistema.</p>'' ||'),
unistr('                      ''<p>Abaixo seguem os detalhes das reservas inclu\00EDdas:</p>'';'),
'',
'        FOR rec IN (',
'            SELECT r.titulo_reserva,',
'                r.des_reserva,',
'                r.tip_reservas,',
'                r.loc,',
'                TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') AS data_inicio,',
'                TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') AS data_fim,',
'                r.num_participantes',
'            FROM reservas r',
'            WHERE r.cod_grupo_reserva = v_id_grupo',
'        )',
'        LOOP',
'            v_bloco_reserva := ''<hr>'' ||',
'                               ''<strong>Nome do Evento:</strong> '' || rec.titulo_reserva || ''<br>'' ||',
unistr('                               ''<strong>Descri\00E7\00E3o:</strong> '' || rec.des_reserva || ''<br>'' ||'),
'                               ''<strong>Tipo:</strong> '' || rec.tip_reservas || ''<br>'';',
'            ',
'            IF LOWER(rec.tip_reservas) = ''mezanino'' THEN',
'                v_bloco_reserva := v_bloco_reserva ||',
unistr('                                   ''<strong>N\00FAmero de Pessoas:</strong> '' || rec.num_participantes || ''<br>'' ||'),
unistr('                                   ''<strong>Per\00EDodos Reservados:</strong><br>'';'),
'',
'                FOR h IN (',
'                    SELECT TO_CHAR(dat, ''DD/MM/YYYY'') AS data_str,',
'                        hor_inicio AS hora_ini,',
'                        hor_fim AS hora_fim',
'                    FROM horarios_mezanino',
'                    WHERE id_reserva = (',
'                        SELECT id_reserva FROM reservas',
'                        WHERE titulo_reserva = rec.titulo_reserva',
'                            AND cod_grupo_reserva = v_id_grupo',
'                        FETCH FIRST 1 ROWS ONLY',
'                    )',
'                    ORDER BY dat, hor_inicio',
'                ) LOOP',
'                    v_bloco_reserva := v_bloco_reserva ||',
unistr('                        ''&nbsp;&nbsp;- '' || h.data_str || '': '' || h.hora_ini || '' \00E0s '' || h.hora_fim || ''<br>'';'),
'                END LOOP;',
'',
'            ELSIF LOWER(rec.tip_reservas) = ''adesivagem'' THEN',
'                v_bloco_reserva := v_bloco_reserva ||',
unistr('                                   ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'';'),
'            ',
'            ELSE',
'                v_bloco_reserva := v_bloco_reserva ||',
'                                   ''<strong>Local:</strong> '' || rec.loc || ''<br>'' ||',
unistr('                                   ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'';'),
'            END IF;',
'',
'            v_mensagem := v_mensagem || v_bloco_reserva;',
'',
'        END LOOP;',
'',
'        v_mensagem := v_mensagem ||',
unistr('                      ''<p><br>Essas solicita\00E7\00F5es est\00E3o agora em an\00E1lise pela equipe respons\00E1vel.</p>'' ||'),
unistr('                      ''<p>Voc\00EA receber\00E1 um novo e-mail quando as reservas forem avaliadas.</p>'' ||'),
'                      ''<p>Atenciosamente,<br>'' ||',
unistr('                      ''Assessoria de Qualidade e Log\00EDstica - ASQUALOG<br>'' ||'),
'                      ''<a href="mailto:'' || v_email_remetente || ''">'' || v_email_remetente || ''</a></p>'';',
'        ',
'        APEX_MAIL.SEND(',
'            p_to        => v_email_destino,',
'            p_from      => v_email_remetente,',
'            p_subj      => v_assunto,',
'            p_body      => NULL,',
'            p_body_html => v_mensagem',
'        );',
'',
'        SELECT COUNT(*) INTO v_total_andamento',
'        FROM reservas',
'        WHERE pendente = ''N''',
'            AND status = ''Em Andamento'';',
'',
unistr('        v_assunto := ''Novas Solicita\00E7\00F5es de Reserva - '' || v_nome;'),
'',
'        v_mensagem := ''<p>Prezado(a) equipe da ASQUALOG,</p>'' ||',
unistr('                      ''<p>O(a) solicitante <strong>'' || v_nome || ''</strong> realizou novas solicita\00E7\00F5es de reserva, conforme os detalhes abaixo:</p>'';'),
'',
'        FOR rec IN (',
'            SELECT r.titulo_reserva,',
'                r.des_reserva,',
'                r.tip_reservas,',
'                r.loc,',
'                TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') AS data_inicio,',
'                TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') AS data_fim,',
'                r.num_participantes',
'            FROM reservas r',
'            WHERE r.cod_grupo_reserva = v_id_grupo',
'        )',
'        LOOP',
'            v_mensagem := v_mensagem ||',
'                          ''<hr>'' ||',
'                          ''<strong>Evento:</strong> '' || rec.titulo_reserva || ''<br>'' ||',
unistr('                          ''<strong>Descri\00E7\00E3o:</strong> '' || rec.des_reserva || ''<br>'' ||'),
'                          ''<strong>Tipo:</strong> '' || rec.tip_reservas || ''<br>'' ||',
'                          ''<strong>Local:</strong> '' || rec.loc || ''<br>'' ||',
unistr('                          ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'';'),
'        END LOOP;',
'',
'        v_mensagem := v_mensagem ||',
unistr('                      ''<p><br><strong>Total de reservas atualmente em an\00E1lise:</strong> '' || v_total_andamento || ''</p>'' ||'),
unistr('                      ''<p>Por favor, acessem o sistema para avaliar as novas solicita\00E7\00F5es.</p>'' ||'),
unistr('                      ''<p>Atenciosamente,<br>Sistema de Reservas de Comunica\00E7\00E3o Institucional - RESCOM</p>'';'),
'',
'        APEX_MAIL.SEND(',
'            p_to        => ''sequalog-equipe@senado.gov.br'',',
'            p_from      => v_email_remetente,',
'            p_subj      => v_assunto,',
'            p_body      => NULL,',
'            p_body_html => v_mensagem',
'        );',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            NULL;',
'    END;',
'',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>141427581228009905
);
end;
