'function toggleRegion(regionId) {',
'    const region = document.getElementById(regionId);',
'    const icon = document.getElementById(''icon_'' + regionId);',
'    const button = document.getElementById(''btn_'' + regionId);',
'        ',
'    if (region.style.display === ''none'') {',
'        region.style.display = ''block'';',
'        icon.classList.remove(''fa-chevron-down'');',
'        icon.classList.add(''fa-chevron-up'');',
'        button.style.display = ''inline-block'';',
'        ',
'        if (!region.dataset.loaded) {',
'            const grupoId = regionId.replace(''grupo_'', ''''); // Pega o id do grupo',
'',
unistr('            // Utiliza do processo dessa p\00E1gina passando o id do grupo'),
'            apex.server.process(''LOAD_REPORT_BY_GROUP'', {',
'                x01: grupoId',
'            }, {',
unistr('                // Se der certo, retorna o relat\00F3rio do grupo e marca true para que n\00E3o recarregar no futuro'),
