'                    const targetDiv = document.getElementById(''relatorio_'' + grupoId);',
'                    if (targetDiv) {',
'                        targetDiv.innerHTML = data.html;',
'                        region.dataset.loaded = "true";',
'                    }',
'                },',
'                error: function(jqXHR, textStatus, errorThrown) {',
unistr('                    console.error("Erro ao carregar o relat\00F3rio:", textStatus, errorThrown);'),
