,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(140955698394608223)
,p_plug_display_sequence=>60
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.ID_RESERVA,',
'       r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       r.STATUS,',
'       r.NUM_PARTICIPANTES,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       LPAD(r.COD_PESSOA, 11, ''0'') as CPF,',
'       r.PENDENTE,',
'       r.LOC,',
'       r.JUSTIFICATIVA,',
'       r.OBS,',
'       dbms_lob.getlength(r.ARQ) as foto,',
'       CASE',
'        WHEN r.status = ''Confirmado'' THEN ''confirmed''',
'        WHEN r.status = ''Realizado'' THEN ''realizado''',
'       END AS css_class,',
'       INITCAP(v.nom_pessoa) as Solicitante,',
'       v.sgl_orgao_exercicio as orgao',
'  from RESERVAS r',
'  join dda.vinculo_sf v ON LPAD(r.COD_PESSOA, 11, ''0'') = v.num_cpf',
'  where r.status IN (''Confirmado'', ''Realizado'')',
'    and (:P11_FILTRO IS NULL OR r.tip_reservas = :P11_FILTRO)',
'    and (:P11_INICIO IS NULL OR r.dat_inicio >= :P11_INICIO)',
'    and (:P11_FIM IS NULL OR r.dat_inicio <= :P11_FIM)',
'    AND (',
'      :P11_TITULO IS NULL OR ',
'      REGEXP_LIKE(UPPER(r.titulo_reserva), ''(^| )'' || UPPER(:P11_TITULO))',
'    )',
'    AND (',
'        :P11_SETOR IS NULL',
'        OR v.sgl_orgao_exercicio IN (',
'            SELECT TRIM(COLUMN_VALUE)',
'            FROM TABLE(apex_string.split(:P11_SETOR, '':''))',
'      )',
'    )',
'  order by r.dat_inicio, r.tip_reservas, r.id_reserva',
' '))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P11_FILTRO,P11_INICIO,P11_FIM,P11_TITULO,P11_SETOR'
