wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(166635795719734015)
,p_plug_name=>'Grupos de Reservas para Avaliar'
,p_region_name=>'regiao_grupos'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(140965489666608226)
,p_plug_display_sequence=>10
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_grupos        APEX_T_VARCHAR2;',
'    l_grupo         VARCHAR2(100);',
'    l_url           VARCHAR2(4000);',
'BEGIN',
'    -- Buscar todos os grupos distintos',
'    SELECT DISTINCT cod_grupo_reserva',
'    BULK COLLECT INTO l_grupos',
'    FROM reservas',
'    WHERE cod_grupo_reserva IS NOT NULL',
'      AND email_enviado = ''N''',
'    ORDER BY cod_grupo_reserva;',
'',
unistr('    -- Verificar se h\00E1 grupos'),
'    IF l_grupos.COUNT = 0 THEN',
'        HTP.P(''<div class="t-Region t-Region--noContent">'');',
'        HTP.P(''<div class="t-Region-body">'');',
unistr('        HTP.P(''<p><strong>N\00E3o h\00E1 reservas para se avaliar.</strong></p>'');'),
'        HTP.P(''</div>'');',
'        HTP.P(''</div>'');',
'    END IF;',
'',
'    -- Gerar HTML para cada grupo',
'    FOR i IN 1..l_grupos.COUNT LOOP',
'        l_grupo := l_grupos(i);',
'        ',
'        l_url := apex_util.prepare_url(',
'            p_url => ''f?p='' || :APP_ID || '':202:'' || :APP_SESSION || ''::NO::P202_COD_GRUPO_RESERVA:'' || l_grupo',
'        );',
'        ',
unistr('        -- HTML da regi\00E3o colaps\00E1vel'),
'        HTP.P(''<div class="t-Region t-Region--accent1 t-Region--textContent t-Region--scrollBody" style="margin-bottom: 10px;">'');',
'        HTP.P(''<div class="t-Region-header">'');',
'        HTP.P(''<div class="t-Region-headerItems t-Region-headerItems--title">'');',
'        ',
'        HTP.P(''<h2 class="t-Region-title">'');',
'        HTP.P(''<button class="t-Button t-Button--noLabel t-Button--icon t-Button--iconLeft" onclick="toggleRegion(''''grupo_'' || REPLACE(l_grupo, '' '', ''_'') || '''''')" type="button">'');',
'        HTP.P(''<span class="t-Icon fa fa-chevron-down" id="icon_grupo_'' || REPLACE(l_grupo, '' '', ''_'') || ''"></span>'');',
'        HTP.P(''</button>'');',
'        HTP.P(''Grupo: '' || APEX_ESCAPE.HTML(l_grupo));',
'        HTP.P(''</h2>'');',
'',
'        HTP.P(''</div>'');',
'',
unistr('        -- Bot\00E3o \00E0 direita (escondido inicialmente)'),
'        HTP.P(''<div class="t-Region-headerItems t-Region-headerItems--controls">'');',
'        HTP.P(''<a id="btn_grupo_'' || REPLACE(l_grupo, '' '', ''_'') || ''" '' ||',
'              ''href="'' || l_url || ''" '' ||',
'              ''style="display:none;" '' ||',
'              ''class="t-Button botao-confirmar">Mandar e-mail</a>'');',
'        HTP.P(''</div>'');',
'',
'',
'        HTP.P(''</div>'');',
'',
unistr('        -- Conte\00FAdo colaps\00E1vel (inicialmente oculto)'),
'        HTP.P(''<div class="t-Region-body" id="grupo_'' || REPLACE(l_grupo, '' '', ''_'') || ''" style="display: none;">'');',
'        HTP.P(''<div id="relatorio_'' || REPLACE(l_grupo, '' '', ''_'') || ''">'');',
unistr('        HTP.P(''<!-- Conte\00FAdo ser\00E1 carregado dinamicamente -->'');'),
'        HTP.P(''</div>'');',
'        HTP.P(''</div>'');',
'        HTP.P(''</div>'');',
'    END LOOP;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
