wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(166635996867734017)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_REPORT_BY_GROUP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Cria os relat\00F3rios de reservas dos grupos'),
'DECLARE',
'    l_grupo         NUMBER := TO_NUMBER(APEX_APPLICATION.G_X01);',
'    l_html          CLOB;',
'    l_url           CLOB;',
'    l_imagem_url    CLOB;',
'BEGIN',
unistr('    -- Faz o html do relat\00F3rio para ser completado depois'),
'    l_html := q''[',
'    <div class="t-Report t-Report--altRowsDefault">',
'      <table class="linha-tabela t-Report-report">',
'        <thead>',
'          <tr>',
'            <th>Analisar</th>',
'            <th>Status</th>',
'            <th>ID</th>',
'            <th class="col-name">Nome da Reserva</th>',
unistr('            <th class="col-"desc>Descri\00E7\00E3o</th>'),
'            <th>Tipo</th>',
unistr('            <th>In\00EDcio</th>'),
'            <th>Fim</th>',
'            <th class="col-"local>Local</th>',
'            <th>Estimativa (Pessoas)</th>',
unistr('            <th>Observa\00E7\00E3o</th>'),
'            <th>Solicitante</th>',
unistr('            <th class="col-"orgao>\00D3rg\00E3o</th>'),
'            <th>Arquivo</th>',
'          </tr>',
'        </thead>',
'        <tbody>',
'    ]'';',
'',
'    -- Faz um loop para pegar os dados',
'    FOR rec IN (',
'        SELECT',
'            r.id_reserva,',
'            r.titulo_reserva,',
'            r.des_reserva,',
'            r.obs,',
'            r.dat_inicio,',
'            r.dat_fim,',
'            r.tip_reservas,',
'            r.loc,',
'            r.num_participantes,',
'            r.mimetype,',
'            v.nom_pessoa,',
'            o.sgl_orgao || '' - '' || o.nom_orgao || '' ('' || o.sgl_orgao_hierarquia || '')'' AS orgao_formatado,',
'            NVL(DBMS_LOB.getlength(r.arq), 0) AS foto_tamanho,',
'            r.status',
'        FROM reservas r',
'        JOIN dda.vinculo_sf v ON v.num_cpf = LPAD(TO_CHAR(r.cod_pessoa), 11, ''0'')',
'        JOIN dda.orgao o ON o.sgl_orgao = v.sgl_orgao_exercicio',
'        JOIN (',
'            SELECT fk_atendimento_reservas_reservas, des_atendimento',
'            FROM (',
'                SELECT a.fk_atendimento_reservas_reservas,',
'                    a.des_atendimento,',
'                    ROW_NUMBER() OVER (',
'                        PARTITION BY a.fk_atendimento_reservas_reservas',
'                        ORDER BY a.dat_criacao_atendimento DESC, a.pk_atendimento_reservas DESC',
'                    ) AS rn',
'                FROM atendimento_reservas a',
'            )',
'            WHERE rn = 1',
'        ) ult',
'            ON r.id_reserva = ult.fk_atendimento_reservas_reservas',
'        WHERE r.cod_grupo_reserva = l_grupo',
'            AND v.ind_vinculo_ativo = ''S''',
unistr('            AND NVL(ult.des_atendimento, ''x'') <> ''Reserva cancelada pelo pr\00F3prio solicitante.'''),
'        ORDER BY r.tip_reservas, r.id_reserva',
'    ) LOOP',
'        l_url := apex_util.prepare_url(',
'            p_url => ''f?p='' || :APP_ID || '':201:'' || :APP_SESSION || ''::NO::P201_ID_RESERVA,P201_COD_GRUPO_RESERVA:'' || rec.id_reserva || '','' || l_grupo',
'        );',
'',
'        l_imagem_url := apex_util.prepare_url(',
'            p_url => ''f?p='' || :APP_ID || '':203:'' || :APP_SESSION || ''::NO::P203_ID_RESERVA:'' || rec.id_reserva',
'        );',
'',
'        l_html := l_html || ''<tr>'';',
'        l_html := l_html || ''<td style="border: 1px solid #ccc;">'' ||',
'            ''<a href="'' || l_url || ''" '' ||',
'            ''class="t-Button t-Button--noLabel t-Button--icon t-Button--small" '' ||',
'            ''title="Ver Detalhes">'' ||',
'            ''<span class="fa fa-eye" aria-hidden="true"></span></a></td>'';',
'',
'        DECLARE',
'            l_check_opacity VARCHAR2(20);',
'            l_x_opacity     VARCHAR2(20);',
'        BEGIN',
'            -- Define opacidades com base no status',
'            IF rec.status = ''Confirmado'' THEN',
'                l_check_opacity := ''opacity:1;'';',
'                l_x_opacity     := ''opacity:0.2;'';',
'            ELSIF rec.status = ''Cancelado'' THEN',
'                l_check_opacity := ''opacity:0.2;'';',
'                l_x_opacity     := ''opacity:1;'';',
'            ELSE',
'                l_check_opacity := ''opacity:0.2;'';',
'                l_x_opacity     := ''opacity:0.2;'';',
'            END IF;',
'',
'            l_html := l_html || ',
'                ''<td style="border: 1px solid #ccc;">'' ||',
unistr('                    -- Coluna com \00EDcones de a\00E7\00E3o (check e X)'),
'                    ''<span class="fa fa-check" style="margin-right:8px; background-color:#28a745; border-color:#28a745; color:white;'' || l_check_opacity || ''" title="Confirmar"></span>'' ||',
'                    ''<span class="fa fa-times" style="background-color:#dc3545; border-color:#dc3545; color:white;'' || l_x_opacity || ''" title="Cancelar"></span>'' ||',
'                ''</td>'';',
'        END;',
'        ',
unistr('        -- Popula as linhas do relat\00F3rio'),
'        l_html := l_html || ''<td>'' || rec.id_reserva || ''</td>'';',
'        l_html := l_html || ''<td class="col-name">'' || APEX_ESCAPE.HTML(rec.titulo_reserva) || ''</td>'';',
'        l_html := l_html || ''<td class="col-desc">'' || APEX_ESCAPE.HTML(rec.des_reserva) || ''</td>'';',
'        l_html := l_html || ''<td>'' || APEX_ESCAPE.HTML(rec.tip_reservas) || ''</td>'';',
'        l_html := l_html || ''<td>'' || TO_CHAR(rec.dat_inicio, ''DD/MM/YYYY'') || ''</td>'';',
'        l_html := l_html || ''<td>'' || TO_CHAR(rec.dat_fim, ''DD/MM/YYYY'') || ''</td>'';',
'        l_html := l_html || ''<td class="col-local">'' || ',
'            CASE WHEN rec.loc IS NULL OR TRIM(rec.loc) IS NULL THEN ''Sem Local'' ',
'                 ELSE APEX_ESCAPE.HTML(rec.loc) ',
'            END || ''</td>'';',
'',
'        l_html := l_html || ''<td>'' || ',
'            CASE WHEN rec.num_participantes IS NULL THEN ''Sem Estimativa'' ',
'                 ELSE TO_CHAR(rec.num_participantes) ',
'            END || ''</td>'';',
'        l_html := l_html || ''<td>'' || ',
'            CASE WHEN rec.obs IS NULL OR TRIM(rec.obs) IS NULL THEN ''---'' ',
'                 ELSE APEX_ESCAPE.HTML(rec.obs) ',
'            END || ''</td>'';',
'        l_html := l_html || ''<td>'' || APEX_ESCAPE.HTML(rec.nom_pessoa) || ''</td>'';',
'        l_html := l_html || ''<td class="col-orgao">'' || APEX_ESCAPE.HTML(rec.orgao_formatado) || ''</td>'';',
'',
'        -- Coluna Foto: Link de download se existir BLOB',
'        IF rec.foto_tamanho > 0 THEN',
'            l_html := l_html || ''<td style="text-align: center;">'' ||',
'                ''<a href="'' || l_imagem_url || ''" download title="Baixar Foto">'' ||',
'                ''<span class="fa fa-download" aria-hidden="true" style="font-size: 16px;"></span>'' ||',
'                ''</a></td>'';',
'        ELSE',
unistr('            l_html := l_html || ''<td style="text-align: center;">\2014</td>'';'),
'        END IF;',
'',
'        l_html := l_html || ''</tr>'';',
'    END LOOP;',
'',
'    l_html := l_html || ''</tbody></table></div>'';',
'',
'    -- Retorna o HTML como JSON',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''html'', l_html);',
'    APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>166635996867734017
);
end;
/
