wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(156652830103616845)
,p_chart_id=>wwv_flow_imp.id(156652333419616845)
,p_seq=>10
,p_name=>unistr('S\00E9rie 1')
,p_data_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_sql   CLOB;',
'    v_meses VARCHAR2(4000);',
'    v_setor VARCHAR2(4000);',
'BEGIN',
'    IF :P12_FILTRO_MES IS NOT NULL THEN',
'        v_meses := '''''''' || REPLACE(:P12_FILTRO_MES, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    IF :P12_FILTRO_SETOR IS NOT NULL THEN',
'        v_setor := '''''''' || REPLACE(:P12_FILTRO_SETOR, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    v_sql := ''',
'        SELECT',
'            R.TIP_RESERVAS,',
'            COUNT(*) AS TOTAL',
'        FROM',
'            RESERVAS R',
'        WHERE 1=1 ',
'            AND R.STATUS = ''''Confirmado'''' '';',
'',
'    IF v_meses IS NOT NULL THEN',
'        v_sql := v_sql || '' AND TO_CHAR(R.DAT_INICIO, ''''MM/YYYY'''') IN ('' || v_meses || '')'';',
'    END IF;',
'',
'    IF v_setor IS NOT NULL THEN',
'        v_sql := v_sql || ''',
'        AND EXISTS (',
'            SELECT 1 FROM DDA.VINCULO_SF VS',
'            WHERE LPAD(R.COD_PESSOA, 11, ''''0'''') = VS.num_cpf',
'              AND VS.SGL_ORGAO_EXERCICIO IN ('' || v_setor || '')',
'        )'';',
'    END IF;',
'',
'    v_sql := v_sql || ''',
'        GROUP BY R.TIP_RESERVAS',
'        ORDER BY R.TIP_RESERVAS'';',
'',
'    RETURN v_sql;',
'END;',
''))
,p_ajax_items_to_submit=>'P12_FILTRO_TIPO,P12_FILTRO_MES,P12_FILTRO_SETOR'
,p_items_value_column_name=>'TOTAL'
,p_items_label_column_name=>'TIP_RESERVAS'
,p_items_label_rendered=>true
,p_items_label_position=>'outsideSlice'
,p_items_label_display_as=>'COMBO'
);
