'',
'    IF v_tipo IS NOT NULL THEN',
'        v_sql := v_sql || '' AND R.TIP_RESERVAS IN ('' || v_tipo || '')'';',
'    END IF;',
'',
'    v_sql := v_sql || ''',
'        GROUP BY VS.SGL_ORGAO_EXERCICIO',
