wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(186247567889183438)
,p_chart_id=>wwv_flow_imp.id(186247410876183437)
,p_seq=>10
,p_name=>unistr('Quantidade de Reservas por M\00EAs')
,p_data_source_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_sql   CLOB;',
'    v_tipos VARCHAR2(4000);',
'    v_setor VARCHAR2(4000);',
'BEGIN',
unistr('    -- Monta os filtros com m\00FAltiplos valores (se houver)'),
'    IF :P12_FILTRO_TIPO IS NOT NULL THEN',
'        v_tipos := '''''''' || REPLACE(:P12_FILTRO_TIPO, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    IF :P12_FILTRO_SETOR IS NOT NULL THEN',
'        v_setor := '''''''' || REPLACE(:P12_FILTRO_SETOR, '':'', '''''','''''') || '''''''';',
'    END IF;',
'',
'    v_sql := ''',
'        WITH MESES AS (',
'            SELECT TO_CHAR(ADD_MONTHS(TRUNC(SYSDATE, ''''YEAR''''), LEVEL - 1), ''''MM/YYYY'''') AS MES',
'            FROM DUAL',
'            CONNECT BY LEVEL <= 12',
'        ),',
'        RESERVAS_AGRUPADAS AS (',
'            SELECT',
'                TO_CHAR(R.DAT_INICIO, ''''MM/YYYY'''') AS MES,',
'                COUNT(*) AS QTD',
'            FROM RESERVAS R',
'            WHERE 1 = 1'';',
'',
'    -- Filtro por tipo',
'    IF v_tipos IS NOT NULL THEN',
'        v_sql := v_sql || '' AND R.TIP_RESERVAS IN ('' || v_tipos || '')'';',
'    END IF;',
'',
'    -- Filtro por setor',
'    IF v_setor IS NOT NULL THEN',
'        v_sql := v_sql || ''',
'            AND EXISTS (',
'                SELECT 1 FROM DDA.VINCULO_SF VS',
'                WHERE LPAD(R.COD_PESSOA, 11, ''''0'''') = VS.NUM_CPF',
'                AND VS.SGL_ORGAO_EXERCICIO IN ('' || v_setor || '')',
'            )'';',
'    END IF;',
'',
'    v_sql := v_sql || ''',
'            GROUP BY TO_CHAR(R.DAT_INICIO, ''''MM/YYYY'''')',
'        )',
'        SELECT',
'            M.MES AS label,',
'            NVL(R.QTD, 0) AS value,',
'            ''''Reservas'''' AS series',
'        FROM MESES M',
'        LEFT JOIN RESERVAS_AGRUPADAS R ON M.MES = R.MES',
'        ORDER BY TO_DATE(M.MES, ''''MM/YYYY'''')'';',
'',
'    RETURN v_sql;',
'END;'))
,p_ajax_items_to_submit=>'P12_FILTRO_TIPO,P12_FILTRO_SETOR'
,p_series_name_column_name=>'SERIES'
,p_items_value_column_name=>'VALUE'
