,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// ------------------- IN\00CDCIO DO C\00D3DIGO DE ATUALIZA\00C7\00C3O AP\00D3S DOWNLOAD -------------------'),
'',
'let pdfDownloadIniciado = false;',
'',
unistr('// Listener de clique no bot\00E3o original do di\00E1logo de download'),
'document.addEventListener(''click'', function(event) {',
'    const downloadButton = event.target.closest(''.a-IRR-dialog--download .ui-dialog-buttonpane .ui-button--hot'');',
'    if (downloadButton) {',
'        const formatoSelecionado = document.getElementById(''reservas_download_format'')?.value;',
'        if (formatoSelecionado === ''PDF'') {',
unistr('            alert(''O seu relat\00F3rio PDF ser\00E1 preparado. A p\00E1gina ser\00E1 atualizada automaticamente ap\00F3s o download.'');'),
'            pdfDownloadIniciado = true;',
'        } else {',
'            setTimeout(function() {',
'                apex.region("reservas").refresh();',
'            }, 500);',
'        }',
'    }',
'});',
'',
'// Listener para quando a janela volta ao foco (detecta fim do download de PDF)',
'window.addEventListener(''focus'', function() {',
'    if (pdfDownloadIniciado) {',
'        apex.region("reservas").refresh();',
'        pdfDownloadIniciado = false;',
'    }',
'});',
'',
unistr('// ------------------- FIM DO C\00D3DIGO DE ATUALIZA\00C7\00C3O AP\00D3S DOWNLOAD -------------------'),
'',
'',
unistr('// ------------------- IN\00CDCIO DO C\00D3DIGO PARA SIMULAR A ABERTURA DA MODAL de DOWNLOAD -------------------'),
'',
'const actionsButton = $(''#reservas_actions_button'');',
'const menuSelector = ''#'' + actionsButton.attr(''data-menu'');',
'',
'if (actionsButton.length === 0) {',
unistr('    console.error("Bot\00E3o ''A\00E7\00F5es'' n\00E3o encontrado.");'),
'    return;',
'}',
'',
unistr('// Passo 1: Abre o menu de ''A\00E7\00F5es'''),
'if (!actionsButton.hasClass(''is-active'')) {',
'    actionsButton.click();',
'}',
'',
'// Passo 2: Espera o menu renderizar e clica no item ''Fazer Download''',
'setTimeout(function() {',
'    const menuElement = $(menuSelector);',
'    const downloadButtonInMenu = menuElement.find(''button:contains("Fazer Download")'');',
'',
'    if (downloadButtonInMenu.length > 0) {',
'        const nativeButton = downloadButtonInMenu[0];',
'        nativeButton.focus();',
'        nativeButton.dispatchEvent(new MouseEvent(''mousedown'', { bubbles: true, cancelable: true }));',
'        nativeButton.dispatchEvent(new MouseEvent(''mouseup'', { bubbles: true, cancelable: true }));',
'        nativeButton.dispatchEvent(new MouseEvent(''click'', { bubbles: true, cancelable: true }));',
'    } else {',
unistr('        console.error("Bot\00E3o ''Fazer Download'' n\00E3o encontrado.");'),
'    }',
'}, 200);',
'',
unistr('// ------------------- FINAL DO C\00D3DIGO PARA SIMULAR A ABERTURA DA MODAL de DOWNLOAD -------------------'),
''))
);
end;
/
prompt --application/pages/page_00014
begin
wwv_flow_imp_page.create_page(
 p_id=>14
,p_name=>'Reserva do Mezanino'
,p_alias=>'RESERVA-DO-MEZANINO'
,p_step_title=>'Reserva do Mezanino'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var datass = '''';',
'var DataArr = [];',
'',
'PDFJS.workerSrc = '''';',
'',
'function setupFileListener() {',
'    apex.server.process(',
'        "NOME_DO_PROCESSO",',
'        {},',
'        {',
'            success: function(pData) {',
'                console.log("pData:", pData);',
'                console.log("COUNT =", pData.count_value);',
'',
'                if (pData.count_value == 1) {',
unistr('                    console.log("COUNT \00E9 1");'),
'                } else {',
'                    console.log("COUNT diferente de 1");',
'                }',
'            },',
'            error: function(error) {',
'                console.error("Erro no processo AJAX:", error);',
'            }',
'        }',
'    );',
'',
'    var fileInput = document.querySelector("#P14_ARQ");',
'    ',
'    if (fileInput) {',
'        fileInput.addEventListener(''change'', function(e) {',
'            if (this.files && this.files[0]) {',
'                console.log("Arquivo selecionado, iniciando processamento...");',
'                // Aguarda um breve momento para garantir o upload',
'                setTimeout(function() {',
'                    ExtractText();',
'                }, 500);',
'            }',
'        });',
'    }',
'}',
'',
unistr('// Chame esta fun\00E7\00E3o quando a p\00E1gina carregar'),
'$(document).ready(function() {',
'    setupFileListener();',
'});',
'',
'function ExtractText() {',
unistr('    console.log("Iniciando a extra\00E7\00E3o do texto...");'),
'',
'    // Captura o <input type="file"> interno do item APEX',
'    var fileInput = document.querySelector("#P14_ARQ");',
'    if (!fileInput || !fileInput.files || fileInput.files.length === 0) {',
'        console.error("Nenhum arquivo selecionado!");',
'        return;',
'    }',
'',
'    var file = fileInput.files[0];',
'',
'    var fReader = new FileReader();',
'',
'    fReader.readAsDataURL(file);',
'    fReader.onloadend = function(event) {',
'        convertDataURIToBinary(event.target.result);',
'    }',
'}',
'',
'var BASE64_MARKER = '';base64,'';',
'',
'function convertDataURIToBinary(dataURI) {',
'    var base64Index = dataURI.indexOf(BASE64_MARKER) + BASE64_MARKER.length;',
'    var base64 = dataURI.substring(base64Index);',
'    var raw = window.atob(base64);',
'    var rawLength = raw.length;',
'',
'    var array = new Uint8Array(new ArrayBuffer(rawLength));',
'',
'    for (var i = 0; i < rawLength; i++) {',
'        array[i] = raw.charCodeAt(i);',
'    }',
'',
'    pdfAsArray(array)',
'}',
'',
'function getPageText(pageNum, PDFDocumentInstance) {',
'    // Return a Promise that is solved once the text of the page is retrieven',
'    return new Promise(function(resolve, reject) {',
'        PDFDocumentInstance.getPage(pageNum).then(function(pdfPage) {',
'            // The main trick to obtain the text of the PDF page, use the getTextContent method',
'            pdfPage.getTextContent().then(function(textContent) {',
'                var textItems = textContent.items;',
'                var finalString = "";',
'',
'                // Concatenate the string of the item to the final string',
'                for (var i = 0; i < textItems.length; i++) {',
'                    var item = textItems[i];',
'                    finalString += item.str + " ";',
'                }',
'',
'                // Solve promise with the text retrieven from the page',
'                resolve(finalString);',
'            });',
'        });',
'    });',
'}',
'',
'function pdfAsArray(pdfAsArray) {',
'    PDFJS.getDocument(pdfAsArray).then(function(pdf) {',
'        var pdfDocument = pdf;',
'        var pagesPromises = [];',
'',
'        for (var i = 0; i < pdf.pdfInfo.numPages; i++) {',
'            (function(pageNumber) {',
'                pagesPromises.push(getPageText(pageNumber, pdfDocument));',
'            })(i + 1);',
'        }',
'',
'        Promise.all(pagesPromises).then(function(pagesText) {',
'            var outputStr = "";',
'            var div = document.getElementById("output");',
'',
'            for (var pageNum = 0; pageNum < pagesText.length; pageNum++) {',
'                console.log(pagesText[pageNum]);',
'                var pageText = pagesText[pageNum];',
'',
'                outputStr = "<br/><br/>Page " + (pageNum + 1) + " contents <br/><br/>";',
'                div.innerHTML += outputStr + pageText;',
'',
unistr('                // \00BF Extra\00E7\00E3o do "Nome do evento"'),
'                let eventoMatch = pageText.match(/Nome do evento\s*(.*?)\s*TEMA/i);',
'                if (eventoMatch && eventoMatch[1]) {',
'                    let evento = eventoMatch[1].trim();',
'                    console.log("Evento:", evento);',
'                    apex.item("P14_TITULO_RESERVA").setValue(evento);',
'                }',
'',
unistr('                // \00BF Extra\00E7\00E3o do "Nome" do respons\00E1vel'),
unistr('                let nomeMatch = pageText.match(/t[\00E9e]rmino\005Cs+do\005Cs+evento\005Cs+Nome\005Cs+([\005Cw\00C0-\00FF\005Cs]+?)\005Cs+Telefone/i);'),
'                if (nomeMatch && nomeMatch[1]) {',
'                    let nome = nomeMatch[1].trim();',
'                    console.log("Nome:", nome);',
'                    apex.item("P14_NOME_SOLICITANTE").setValue(nome);',
'                }',
'',
'                let qtdMatch = pageText.match(/Quantidade\s+estimada\s+de\s+convidados\s+(\d+)/i);',
'                if (qtdMatch) {',
'                    apex.item("P14_NUM_PARTICIPANTES").setValue(qtdMatch[1].trim());',
unistr('                    console.log("\00BF Quantidade:", qtdMatch[1]);'),
'                }',
'',
unistr('                // 2\00BF\00BF Hor\00E1rios (in\00EDcio e fim)'),
'                let horaMatch = pageText.match(/Descreva[\s\S]*?(\d{1,2}:\d{2})\s+(\d{1,2}:\d{2})/i);',
'                if (horaMatch) {',
'                    apex.item("P14_HORA_INI").setValue(horaMatch[1]);',
'                    apex.item("P14_HORA_FIM").setValue(horaMatch[2]);',
unistr('                    console.log("\00BF Hor\00E1rios:", horaMatch[1], "-", horaMatch[2]);'),
'                }',
'',
unistr('                // 3\00BF\00BF Descri\00E7\00E3o (at\00E9 antes de \201C1.\201D)'),
'                let descMatch = pageText.match(/\d{1,2}:\d{2}\s+\d{1,2}:\d{2}\s+([^\d]+?)\s+1\./i);',
'                if (descMatch) {',
'                    let descricao = descMatch[1].replace(/\s+/g, " ").trim();',
'                    apex.item("P14_DES_RESERVA").setValue(descricao);',
unistr('                    console.log("\00BF Descri\00E7\00E3o:", descricao);'),
'                }',
'',
unistr('                // 4\00BF\00BF Data (na segunda p\00E1gina)'),
'                let dataMatch = pageText.match(/Data:\s*(\d{2}\/\d{2}\/\d{4})/i);',
'                if (dataMatch) {',
'                    apex.item("P14_DATA").setValue(dataMatch[1]);',
unistr('                    console.log("\00BF Data:", dataMatch[1]);'),
'                }',
'            }',
'            apex.server.process(',
'                "INSERE_TEMP_RESERVAS",',
'                {',
'                    x01: apex.item("P14_NOME_SOLICITANTE").getValue(),',
'                    x02: apex.item("P14_DATA").getValue(),',
'                    x03: apex.item("P14_HORA_INI").getValue(),',
'                    x04: apex.item("P14_HORA_FIM").getValue()',
'                },',
'                {',
'                    success: function(pData) {',
'                        console.log("Processo INSERE_TEMP_RESERVAS executado.", pData);',
'                    },',
'                    error: function(err) {',
'                        console.error("Erro no AJAX:", err);',
'                    }',
'                }',
'            );',
'        });',
'    }, function(reason) {',
'        console.error("Erro ao carregar o PDF:", reason);',
'    });',
'}'))
