wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(351775274881137051)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(1333708621792549513)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Inicializar o form Registrar Mezanino'
,p_internal_uid=>351775274881137051
