wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(350026162159827742)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERE_TEMP_RESERVAS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_nome        VARCHAR2(4000) := apex_application.g_x01;',
'    l_data        VARCHAR2(10)   := apex_application.g_x02;',
'    l_hora_ini    VARCHAR2(10)   := apex_application.g_x03;',
'    l_hora_fim    VARCHAR2(10)   := apex_application.g_x04;',
'',
'    l_cpf         VARCHAR2(11);',
'    l_count     NUMBER;',
'BEGIN',
'    -- 1) VALIDAR NOME',
'    IF l_nome IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20010, ''Por favor, informe o nome do solicitante.'');',
'    END IF;',
'',
unistr('    -- 2) BUSCAR CPF DO NOME (igual seu c\00F3digo anterior)'),
'    SELECT num_cpf',
'      INTO l_cpf',
'      FROM dda.vinculo_sf',
'     WHERE TRANSLATE(LOWER(nom_pessoa),',
unistr('                     ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                     ''aaaaaeeeeeiiiiooooouuuuc'')',
'           LIKE',
'           TRANSLATE(LOWER(l_nome),',
unistr('                     ''\00E3\00E2\00E1\00E0\00E4\00BF\00EA\00E9\00E8\00EB\00EE\00ED\00EC\00EF\00F5\00F4\00F3\00F2\00F6\00FB\00FA\00F9\00FC\00E7'','),
'                     ''aaaaaeeeeeiiiiooooouuuuc'') || ''%''',
'       AND ROWNUM = 1;',
'',
'    SELECT COUNT(*) INTO l_count',
'    FROM tmp_reservas',
'    WHERE cpf_solicitante = l_cpf',
'        AND dat = TO_DATE(l_data, ''DD/MM/YYYY'')',
'        AND hor_inicio = l_hora_ini',
'        AND hor_fim = l_hora_fim;',
'',
'    IF l_count > 0 THEN',
'        apex_json.open_object;',
'        apex_json.write(''status'', ''duplicado'');',
unistr('        apex_json.write(''msg'', ''J\00E1 existe uma reserva id\00EAntica para este CPF.'');'),
'        apex_json.close_object;',
'        RETURN;',
'    END IF;',
'',
'    -- 3) INSERIR NA TMP_RESERVAS',
'    INSERT INTO tmp_reservas (',
'        cpf_solicitante,',
'        dat,',
'        hor_inicio,',
'        hor_fim,',
'        dat_criacao',
'    ) VALUES (',
'        l_cpf,',
'        TO_DATE(l_data, ''DD/MM/YYYY''),',
'        l_hora_ini,',
'        l_hora_fim,',
'        SYSDATE',
'    );',
'',
'    -- 4) RETORNAR DADOS PRO JAVASCRIPT (se quiser)',
'    apex_json.open_object;',
'    apex_json.write(''cpf'', l_cpf);',
'    apex_json.write(''status'', ''ok'');',
'    apex_json.close_object;',
'',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>350026162159827742
);
