,p_name=>unistr('Campos de local/n\00FAmero')
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('// Carrega os campos espec\00EDficos de cada tipo, exibindo ou escondendo eles'),
'var tipo = $v("P101_TIP_RESERVAS").toLowerCase();',
'',
'if (tipo.startsWith("porta")) {',
'    apex.item("P101_LOC").show();',
'    apex.item("P101_DAT_INICIO").show();',
'    apex.item("P101_DAT_FIM").show();',
'',
'    $s("P101_NUM_PARTICIPANTES", "");',
'',
'    $("#region_datas_mezanino").hide();',
'    apex.item("P101_NUM_PARTICIPANTES").hide();',
'} else if (tipo === "mezanino") {',
'    apex.item("P101_NUM_PARTICIPANTES").show();',
'    $("#region_datas_mezanino").show();',
'',
'    $s("P101_LOC", "");',
'',
'    apex.item("P101_DAT_INICIO").hide();',
'    apex.item("P101_DAT_FIM").hide();',
'    apex.item("P101_LOC").hide();',
'} else if (tipo === "adesivagem") {',
'    apex.item("P101_DAT_INICIO").show();',
'    apex.item("P101_DAT_FIM").show();',
'',
'    apex.item("P101_LOC").hide();',
'    apex.item("P101_NUM_PARTICIPANTES").hide();',
'    $("#region_datas_mezanino").hide();',
'} else {',
'    apex.item("P101_LOC").show();',
'    apex.item("P101_NUM_PARTICIPANTES").show();',
'}',
''))
);
