wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(139211771633637407)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Cancelar Reserva'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- C\00F3digo para cancelar reserva e mandar email para o setor respons\00E1vel avisando'),
'DECLARE',
'    v_nome            VARCHAR2(200);',
'    v_status          reservas.status%TYPE;',
'    v_email_setor     VARCHAR2(200) := ''sequalog-equipe@senado.gov.br''; -- Substitua com o e-mail real do setor',
'    v_email_remetente VARCHAR2(200);',
'    v_mensagem        CLOB;',
'BEGIN',
'    SELECT status INTO v_status',
'    FROM reservas',
'    WHERE id_reserva = :P101_ID_RESERVA;',
'',
'    IF v_status != ''Cancelado'' THEN',
'        UPDATE reservas',
'        SET status = ''Cancelado'',',
'            email_enviado = ''S'',',
unistr('            justificativa = ''Cancelado pelo pr\00F3prio solicitante.'''),
'        WHERE id_reserva = :P101_ID_RESERVA;',
'',
unistr('        -- Se o tipo for mezanino, deleta ocorr\00EAncia da tabela de hor\00E1rios'),
'        IF :P101_TIP_RESERVAS = ''Mezanino'' THEN',
'            DELETE FROM horarios_mezanino',
'            WHERE id_reserva = :P101_ID_RESERVA;',
'        END IF;',
'',
'        SELECT nom_pessoa INTO v_nome',
'        FROM dda.vinculo_sf',
'        WHERE num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'          AND ind_vinculo_ativo = ''S'';',
'',
'        SELECT txt_email_sf INTO v_email_remetente',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'',
'        INSERT INTO atendimento_reservas (',
'            dat_criacao_atendimento,',
'            des_atendimento,',
'            nom_atendimento,',
'            fk_atendimento_reservas_reservas,',
'            confirmado',
'        ) VALUES (',
'            SYSDATE,',
unistr('            ''Reserva cancelada pelo pr\00F3prio solicitante.'','),
'            v_nome,',
'            :P101_ID_RESERVA,',
'            ''N''',
'        );',
'',
'        -- Enviar e-mail apenas se o status anterior era ''Confirmado''',
'        IF UPPER(v_status) = ''CONFIRMADO'' THEN',
'            v_mensagem := ''<p>Prezado setor ASQUALOG,</p>'' ||',
unistr('                          ''<p>Informamos que o usu\00E1rio <strong>'' || v_nome || ''</strong> cancelou a pr\00F3pria reserva.</p>'' ||'),
'                          ''<p><strong>ID da Reserva:</strong> '' || :P101_ID_RESERVA || ''<br>'' ||',
'                          ''<strong>Tipo:</strong> '' || :P101_TIP_RESERVAS || ''<br>'' ||',
'                          ''<strong>Data/Hora do Cancelamento:</strong> '' || TO_CHAR(SYSDATE, ''DD/MM/YYYY HH24:MI'') || ''<br>'' ||',
unistr('                          ''<strong>Justificativa:</strong> Cancelado pelo pr\00F3prio solicitante.</p>'' ||'),
'                          ''<p>Atenciosamente,<br>Sistema de Reservas</p>'';',
'',
'            APEX_MAIL.SEND (',
'                p_to        => v_email_setor,',
'                p_from      => v_email_remetente,',
'                p_subj      => ''Reserva CONFIRMADA cancelada pelo solicitante - ID '' || :P101_ID_RESERVA,',
'                p_body      => NULL,',
'                p_body_html => v_mensagem',
'            );',
'        END IF;',
'    END IF;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>139211771633637407
);
end;
