,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Obter datas dos campos',
'var dataInicio = new Date($v("P104_DAT_INICIO"));',
'var dataFim = new Date($v("P104_DAT_FIM"));',
'var hoje = new Date();',
'hoje.setHours(0,0,0,0); // Zera horas para comparar apenas datas',
'',
unistr('// Fun\00E7\00E3o para adicionar dias \00FAteis'),
'function adicionarDiasUteis(data, diasUteis) {',
'    var resultado = new Date(data);',
'    while (diasUteis > 0) {',
'        resultado.setDate(resultado.getDate() + 1);',
'        var diaSemana = resultado.getDay();',
'        if (diaSemana !== 0 && diaSemana !== 6) {',
'            diasUteis--;',
'        }',
'    }',
'    return resultado;',
'}',
'',
'var minInicio = adicionarDiasUteis(hoje, 2);',
'',
unistr('// Valida\00E7\00E3o'),
'if (dataInicio > dataFim) {',
unistr('    apex.message.alert("A data de in\00EDcio n\00E3o pode ser posterior \00E0 data de fim.");'),
'} else if (dataInicio < hoje) {',
unistr('    apex.message.alert("A data de in\00EDcio n\00E3o pode ser no passado.");'),
'} else if (dataInicio < minInicio) {',
unistr('    apex.message.alert("A data de in\00EDcio deve ser com pelo menos 2 dias \00FAteis de anteced\00EAncia.");'),
'} else {',
unistr('    // Datas v\00E1lidas \2013 aplicar no formul\00E1rio pai'),
'    parent.$s("P3_DAT_INICIO", $v("P104_DAT_INICIO"));',
'    parent.$s("P3_DAT_FIM", $v("P104_DAT_FIM"));',
'    parent.apex.navigation.dialog.close(true, {});',
'}',
''))
);
end;
