'    apex.item("P105_DAT_INICIO").show();',
'    apex.item("P105_DAT_FIM").show();',
'',
'    apex.item("P105_LOC").hide();',
'    $("#datas_mezanino").hide();',
'    apex.item("P105_NUM_PARTICIPANTES").hide();',
'} else {',
