,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var errorMsg = apex.item(''P107_ERROR_MESSAGE'').getValue();',
'',
'if (errorMsg === ''SUCCESS'') {',
'    // Sucesso - fecha o dialog',
unistr('    apex.message.showPageSuccess(''Hor\00E1rio reservado com sucesso!'');'),
'    apex.navigation.dialog.close(true);',
'} else if (errorMsg !== '''') {',
'    apex.message.clearErrors();',
'',
unistr('    // H\00E1 erro - mostra a mensagem e cancela o fechamento do dialog'),
'    apex.message.showErrors([{',
'        type: ''error'',',
'        location: ''page'',',
'        message: errorMsg',
'    }]);',
'    ',
'    // Cancela o fechamento do dialog',
'    return false;',
'} else {',
'    // Sem erro e sem sucesso - permite continuar normalmente',
'    return true;',
'}'))
);
