,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.ID_RESERVA,',
'       r.DAT_INICIO,',
'       r.DAT_FIM,',
'       r.TIP_RESERVAS,',
'       r.STATUS,',
'       r.NUM_PARTICIPANTES,',
'       r.TITULO_RESERVA,',
'       r.DES_RESERVA,',
'       v.nom_pessoa,',
'       r.PENDENTE,',
'       r.LOC,',
'       r.JUSTIFICATIVA,',
'       case when r.OBS is null then ''N/A'' else r.OBS end as OBSERVACAO,',
'       r.ARQ,',
'       r.MIMETYPE,',
'       r.FILENAME,',
'       r.COD_GRUPO_RESERVA',
'  from RESERVAS r',
'  join dda.vinculo_sf v on LPAD(r.cod_pessoa, 11, ''0'') = v.num_cpf',
