wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(142683948244056233)
,p_event_id=>wwv_flow_imp.id(142683713031056231)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Quando algu\00E9m abre os detalhes da reserva, automaticamente o atendimento \00E9 atualizado para ''Reserva est\00E1 sendo analisada'''),
'DECLARE',
'    v_nome VARCHAR2(200);',
'    v_ultimo VARCHAR2(4000);',
'BEGIN',
'    SELECT nom_pessoa INTO v_nome',
'    FROM dda.vinculo_sf',
'    WHERE num_cpf = ',
'        CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END;',
'',
'    SELECT des_atendimento INTO v_ultimo',
'    FROM (',
'        SELECT des_atendimento',
'        FROM atendimento_reservas',
'        WHERE fk_atendimento_reservas_reservas = :P201_ID_RESERVA',
'        ORDER BY dat_criacao_atendimento DESC',
'    )',
'    WHERE ROWNUM = 1;',
'',
unistr('    IF v_ultimo = ''Registro da Solicita\00E7\00E3o'' THEN'),
'        INSERT INTO atendimento_reservas (',
'            dat_criacao_atendimento,',
'            des_atendimento,',
'            nom_atendimento,',
'            fk_atendimento_reservas_reservas,',
'            confirmado',
'        ) VALUES (',
'            SYSDATE,',
unistr('            ''Reserva est\00E1 sendo analisada.'','),
'            v_nome,',
'            :P201_ID_RESERVA,',
'            ''S''',
'        );',
'    END IF;',
'END;'))
,p_attribute_02=>'P201_ID_RESERVA'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
