wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(182209942291461503)
,p_event_id=>wwv_flow_imp.id(182209861148461502)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var reservaId = $v(''P201_ID_RESERVA'');',
'var grupoId = $v(''P201_COD_GRUPO_RESERVA'');',
'var justificativa = $v(''P201_JUSTIFICATIVA'');',
'',
'var acao = this.triggeringElement.id.includes("confirmar") ? ''Confirmar'' : ''Cancelar'';',
'',
'// Roda o processo para cancelar a reserva',
'apex.server.process("CONFIRMAR_OU_CANCELAR_RESERVA", {',
'    x01: reservaId,',
'    x02: justificativa,',
'    x03: ''Cancelar''',
'}, {',
'    success: function(pData) {',
unistr('        // Garante que pData \00E9 um objeto'),
'        if (typeof pData === "string") {',
'            try { pData = JSON.parse(pData); } catch(e) { pData = {}; }',
'        }',
'',
'        if (pData.status === "erro") {',
'            // Mostra a mensagem no formato APEX Universal Theme',
'            apex.message.clearErrors(); // limpa mensagens anteriores',
'            apex.message.showErrors([{',
'                type: "error",',
unistr('                location: "page", // exibe no topo do modal/p\00E1gina'),
'                message: pData.mensagem,',
'                unsafe: true // permite HTML',
'            }]);',
'            return;',
'        }',
'',
unistr('        // Continua somente se n\00E3o houve erro e chama outro processo para gerar a url para a p\00E1gina 11 com os atributos certos'),
'        apex.server.process("GERAR_URL_11", {',
'            x01: grupoId',
'        }, {',
'            success: function(pReturn) {',
'                if (pReturn && pReturn.url) {',
'                    window.location.href = pReturn.url;',
'                } else {',
'                    apex.message.showErrors([{',
'                        type: "error",',
'                        location: "page",',
'                        message: "Erro ao gerar URL segura.",',
'                        unsafe: false',
'                    }]);',
'                }',
'            },',
'            error: function() {',
'                apex.message.showErrors([{',
'                    type: "error",',
'                    location: "page",',
'                    message: "Erro ao gerar URL segura.",',
'                    unsafe: false',
'                }]);',
'            }',
'        });',
'    },',
'    error: function() {',
'        apex.message.showErrors([{',
'            type: "error",',
'            location: "page",',
unistr('            message: "Erro na comunica\00E7\00E3o com o servidor.",'),
'            unsafe: false',
'        }]);',
'    }',
'});',
''))
);
