wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(170302014315122015)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Confirmar escolhas e enviar email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Envia email para o solicitante com os detalhes de cada reserva de tal grupo, assim como as respostas para cada reserva',
'DECLARE',
'    v_qtd_em_andamento  INTEGER;',
'    v_nome_solicitante  VARCHAR2(200);',
'    v_nome_asqualog     VARCHAR2(200);',
'    v_email_destino     VARCHAR2(200);',
'    v_email_remetente   VARCHAR2(200) := ''asqualog@senado.leg.br'';',
unistr('    v_assunto           VARCHAR2(200) := ''Atualiza\00E7\00E3o sobre suas reservas'';'),
'    v_mensagem          CLOB;',
'    v_bloco_reserva     CLOB;',
'    v_status_atual      VARCHAR2(50);',
'',
unistr('    -- Fun\00E7\00E3o auxiliar para quebrar linhas longas com <br>'),
'    FUNCTION quebra_linha_html(p_texto CLOB, p_limite INTEGER := 80) RETURN CLOB IS',
'        v_saida   CLOB := '''';',
'        v_linha   VARCHAR2(4000);',
'        v_inicio  PLS_INTEGER := 1;',
'        v_espaco  PLS_INTEGER;',
'    BEGIN',
'        WHILE v_inicio <= LENGTH(p_texto) LOOP',
'            v_espaco := INSTR(SUBSTR(p_texto, v_inicio, p_limite + 1), '' '', -1);',
'            IF v_espaco = 0 THEN',
'                v_espaco := p_limite;',
'            END IF;',
'',
'            v_linha := SUBSTR(p_texto, v_inicio, v_espaco);',
'            v_saida := v_saida || v_linha || ''<br>'';',
'            v_inicio := v_inicio + v_espaco;',
'',
'            WHILE SUBSTR(p_texto, v_inicio, 1) = '' '' LOOP',
'                v_inicio := v_inicio + 1;',
'            END LOOP;',
'        END LOOP;',
'',
'        RETURN v_saida;',
'    END;',
'',
'BEGIN',
'    SELECT COUNT(*) INTO v_qtd_em_andamento',
'    FROM reservas',
'    WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'      AND status = ''Em Andamento'';',
'',
unistr('    -- S\00F3 \00E9 poss\00EDvel mandar o email quando todas as reservas do grupo forem analisadas'),
'    IF v_qtd_em_andamento > 0 THEN',
'        APEX_ERROR.ADD_ERROR(',
'            p_message => ''Ainda existem reservas para ser analisadas. Avalie todas as reservas do grupo antes de confirmar.'',',
'            p_display_location => APEX_ERROR.c_inline_in_notification',
'        );',
'        RETURN;',
'    END IF;',
'',
'    UPDATE reservas',
'    SET email_enviado = ''S''',
'    WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA;',
'',
'    BEGIN',
'        SELECT v.nom_pessoa',
'        INTO v_nome_solicitante',
'        FROM reservas r',
'        JOIN dda.vinculo_sf v',
'          ON v.num_cpf = LPAD(r.cod_pessoa, 11, ''0'')',
'         AND v.ind_vinculo_ativo = ''S''',
'        WHERE r.cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'        FETCH FIRST 1 ROWS ONLY;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_nome_solicitante := ''Solicitante Desconhecido'';',
'    END;',
'',
'    BEGIN',
'        SELECT nom_pessoa INTO v_nome_asqualog',
'        FROM dda.vinculo_sf',
'        WHERE num_cpf = ',
'            CASE',
'                WHEN REGEXP_LIKE(:APP_USER, ''^\d+$'')',
'                    THEN :APP_USER',
'                ELSE (',
'                    SELECT u.num_cpf_pessoa',
'                    FROM dda.usuario_rede u',
'                    WHERE LOWER(u.txt_email_sf) = LOWER(:APP_USER) || ''@senado.leg.br''',
'                )',
'            END',
'          AND ind_vinculo_ativo = ''S'';',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_nome_asqualog := ''Equipe ASQUALOG'';',
'    END;',
'',
'    BEGIN',
'        SELECT txt_email_sf INTO v_email_destino',
'        FROM dda.usuario_rede',
'        WHERE num_cpf_pessoa = (',
'            SELECT LPAD(cod_pessoa, 11, ''0'')',
'            FROM reservas',
'            WHERE cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
'            FETCH FIRST 1 ROWS ONLY',
'        );',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            v_email_destino := ''sem_email@dominio.com'';',
'    END;',
'',
'    v_mensagem := ''<p>Prezado(a) <strong>'' || v_nome_solicitante || ''</strong>,</p>'' ||',
unistr('                  ''<p>Informamos que as reservas solicitadas por voc\00EA passaram por an\00E1lise e tivemos a seguinte decis\00E3o:</p>'';'),
'',
'    FOR rec IN (',
'        SELECT r.id_reserva,',
'               r.titulo_reserva,',
'               r.des_reserva,',
'               r.tip_reservas,',
'               r.loc,',
'               TO_CHAR(r.dat_inicio, ''DD/MM/YYYY'') AS data_inicio,',
'               TO_CHAR(r.dat_fim, ''DD/MM/YYYY'') AS data_fim,',
'               r.num_participantes,',
'               r.status,',
'               r.justificativa',
'        FROM reservas r',
'        JOIN (',
'            SELECT fk_atendimento_reservas_reservas, des_atendimento',
'            FROM (',
'                SELECT a.fk_atendimento_reservas_reservas,',
'                    a.des_atendimento,',
'                    ROW_NUMBER() OVER (',
'                        PARTITION BY a.fk_atendimento_reservas_reservas',
'                        ORDER BY a.dat_criacao_atendimento DESC, a.pk_atendimento_reservas DESC',
'                    ) AS rn',
'                FROM atendimento_reservas a',
'            )',
'            WHERE rn = 1',
'        ) ult',
'            ON r.id_reserva = ult.fk_atendimento_reservas_reservas',
'        WHERE r.cod_grupo_reserva = :P202_COD_GRUPO_RESERVA',
unistr('            AND NVL(ult.des_atendimento, ''x'') <> ''Reserva cancelada pelo pr\00F3prio solicitante.'''),
'    ) LOOP',
'        v_bloco_reserva := ''<hr>'' ||',
'                           ''<strong>Nome do Evento:</strong> '' || rec.titulo_reserva || ''<br>'' ||',
unistr('                           ''<strong>Descri\00E7\00E3o:</strong> '' || rec.des_reserva || ''<br>'' ||'),
'                           ''<strong>Tipo:</strong> '' || rec.tip_reservas || ''<br>'';',
'',
'        IF LOWER(rec.tip_reservas) = ''mezanino'' THEN',
'            v_bloco_reserva := v_bloco_reserva ||',
unistr('                               ''<strong>N\00FAmero de Pessoas:</strong> '' || rec.num_participantes || ''<br>'' ||'),
unistr('                               ''<strong>Per\00EDodos Reservados:</strong><br>'';'),
'',
'            FOR h IN (',
'                SELECT TO_CHAR(dat, ''DD/MM/YYYY'') AS data_str,',
'                       hor_inicio AS hora_ini,',
'                       hor_fim AS hora_fim',
'                FROM horarios_mezanino',
'                WHERE id_reserva = rec.id_reserva',
'                ORDER BY dat, hor_inicio',
'            ) LOOP',
'                v_bloco_reserva := v_bloco_reserva ||',
unistr('                                   ''&nbsp;&nbsp;- '' || h.data_str || '': '' || h.hora_ini || '' \00E0s '' || h.hora_fim || ''<br>'';'),
'            END LOOP;',
'',
'        ELSIF LOWER(rec.tip_reservas) = ''adesivagem'' THEN',
'            v_bloco_reserva := v_bloco_reserva ||',
unistr('                               ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'';'),
'',
'        ELSE',
'            v_bloco_reserva := v_bloco_reserva ||',
'                               ''<strong>Local:</strong> '' || ',
'                                   CASE ',
'                                       WHEN LENGTH(rec.loc) > 80 THEN quebra_linha_html(rec.loc, 80) ',
'                                       ELSE rec.loc',
'                                   END || ''<br>'' ||',
unistr('                               ''<strong>Per\00EDodo:</strong> '' || rec.data_inicio || '' at\00E9 '' || rec.data_fim || ''<br>'';'),
'        END IF;',
'',
'        IF UPPER(rec.status) = ''CONFIRMADO'' THEN',
'            v_bloco_reserva := v_bloco_reserva ||',
'                ''<strong>Status:</strong> <span style="color: green;"><strong>Confirmada</strong></span><br>'' ||',
unistr('                ''A reserva foi <span style="color: green;"><strong>CONFIRMADA</strong></span> e est\00E1 registrada como "Confirmado" no sistema.<br>'' ||'),
unistr('                ''Favor comparecer ao local na data e hor\00E1rio informados.<br><br>'';'),
'',
'        ELSIF UPPER(rec.status) = ''CANCELADO'' THEN',
'            v_bloco_reserva := v_bloco_reserva ||',
'                ''<strong>Status:</strong> <span style="color: red;"><strong>Cancelada</strong></span><br>'' ||',
'                ''Infelizmente, a reserva foi <span style="color: red;"><strong>CANCELADA</strong></span>.<br>'' ||',
'                ''<strong>Motivo:</strong> '' ||',
'                    CASE ',
'                        WHEN LENGTH(rec.justificativa) > 80 THEN quebra_linha_html(rec.justificativa, 80) ',
'                        ELSE rec.justificativa ',
'                    END || ''<br>'' ||',
unistr('                ''Caso tenha d\00FAvidas, entre em contato com a equipe respons\00E1vel.<br><br>'';'),
'        END IF;',
'',
'',
'        v_mensagem := v_mensagem || v_bloco_reserva;',
'    END LOOP;',
'',
'    v_mensagem := v_mensagem ||',
unistr('                  ''<p>Agradecemos sua compreens\00E3o.</p>'' ||'),
'                  ''<p>Atenciosamente,<br>'' || v_nome_asqualog || ''<br>ASQUALOG<br>'' || v_email_remetente || ''</p>'';',
'',
'    APEX_MAIL.SEND (',
'        p_to        => v_email_destino,',
'        p_from      => v_email_remetente,',
'        p_subj      => v_assunto,',
'        p_body      => NULL,',
'        p_body_html => v_mensagem',
'    );',
'',
'    COMMIT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>170302014315122015
);
end;
