'} else if (tipo === "adesivagem") {',
'    apex.item("P204_DAT_INICIO").show();',
'    apex.item("P204_DAT_FIM").show();',
'',
'    apex.item("P204_LOC").hide();',
'    $("#datas_mezanino").hide();',
'    apex.item("P204_NUM_PARTICIPANTES").hide();',
'} else {',
